const reclaimCodeGraphBuild = `-- name: ReclaimCodeGraphBuild :execrows
UPDATE code_graph_index
SET pending_commit = ?, branch = ?, last_error = '', started_at = ?, updated_at = ?
WHERE project_id = ? AND repo_id = ? AND generation = ? AND phase = 'building'
`

type ReclaimCodeGraphBuildParams struct {
	PendingCommit string
	Branch        string
	StartedAt     sql.NullTime
	UpdatedAt     time.Time
	ProjectID     string
	RepoID        string
	Generation    int64
}

// Take over a build left in flight by a crash, conditional on the generation
// the caller read. Two restarts racing to recover one abandoned build cannot
// both proceed.
func (q *Queries) ReclaimCodeGraphBuild(ctx context.Context, arg ReclaimCodeGraphBuildParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, reclaimCodeGraphBuild,
		arg.PendingCommit,
		arg.Branch,
		arg.StartedAt,
		arg.UpdatedAt,
		arg.ProjectID,
		arg.RepoID,
		arg.Generation,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

