const searchCodeGraphSymbols = `-- name: SearchCodeGraphSymbols :many
SELECT project_id, repo_id, generation, symbol_id, path, name, kind, language, line, end_line, signature, doc, summary, summary_source, exported, body_hash, updated_at FROM code_graph_symbols
WHERE project_id = ? AND repo_id = ? AND generation = ?
  AND instr(lower(name) || ' ' || lower(path) || ' ' || lower(summary), ?) > 0
ORDER BY exported DESC, symbol_id
LIMIT ?
`

type SearchCodeGraphSymbolsParams struct {
	ProjectID  string
	RepoID     string
	Generation int64
	Term       string
	Limit      int64
}

// The candidate read behind task-to-graph retrieval. It matches a term against
// the symbol's name, its path and its summary, and it is bounded in SQL rather
// than in Go so a 100k-symbol graph never crosses the boundary.
//
// instr() rather than LIKE: a task term is arbitrary user text, and under LIKE
// a term containing % or _ would silently become a wildcard. instr does a
// literal substring test, so the caller lowercases the term and nothing else
// has to be escaped.
//
// One concatenated haystack rather than three tests, because the term is bound
// once. A term cannot span the joins: normalizeTerms splits on everything that
// is not a letter, a digit, a dash or an underscore, so no term ever contains
// the space the fields are joined with.
func (q *Queries) SearchCodeGraphSymbols(ctx context.Context, arg SearchCodeGraphSymbolsParams) ([]CodeGraphSymbol, error) {
	rows, err := q.db.QueryContext(ctx, searchCodeGraphSymbols,
		arg.ProjectID,
		arg.RepoID,
		arg.Generation,
		arg.Term,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CodeGraphSymbol{}
	for rows.Next() {
		var i CodeGraphSymbol
		if err := rows.Scan(
			&i.ProjectID,
			&i.RepoID,
			&i.Generation,
			&i.SymbolID,
			&i.Path,
			&i.Name,
			&i.Kind,
			&i.Language,
			&i.Line,
			&i.EndLine,
			&i.Signature,
			&i.Doc,
			&i.Summary,
			&i.SummarySource,
			&i.Exported,
			&i.BodyHash,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

